from dataclasses import dataclass
from typing import Dict, List, Optional, Tuple
import os, pathlib, pickle, hashlib, re
import numpy as np
import pandas as pd
import pyranges as pr

def _versionless(tid: str) -> str:
    """Strip version suffix from Ensembl IDs (e.g., ENST00000442987.3 -> ENST00000442987).
    
    Preserves PacBio IDs (PB.10.104) since the last number is the transcript ID, not a version.
    """
    # Don't strip PacBio IDs - the last number is the transcript ID, not a version
    if tid.startswith("PB."):
        return tid
    i = tid.rfind(".")
    return tid[:i] if i > 0 and tid[i + 1:].isdigit() else tid

@dataclass(frozen=True, slots=True)
class TxRecord:
    transcript_id: str
    gene_id: Optional[str]
    gene_name: Optional[str]
    transcript_name: Optional[str]
    transcript_type: Optional[str]
    chrom: str
    strand: int  # +1 / -1
    span: Tuple[int, int]  # (min_start, max_end)
    exons: np.ndarray      # (n,2) int32 [[Start,End],...]
    cds: np.ndarray
    utr5: np.ndarray
    utr3: np.ndarray

    @property
    def junctions(self) -> np.ndarray:
        if self.exons.shape[0] <= 1:
            return np.empty((0, 2), dtype=np.int32)
        ends, starts = self.exons[:-1, 1], self.exons[1:, 0]
        return np.stack([ends, starts], axis=1).astype(np.int32)


class TranscriptIndex:
    """Fast, read-only index built from a GTF/GFF. O(1) lookups for blocks & metadata."""

    def __init__(self, tx_by_id: Dict[str, TxRecord], gene_to_tx: Dict[str, List[str]],
                 genename_to_tx: Dict[str, List[str]], cache_key: str):
        self._tx_by_id = tx_by_id
        self._gene_to_tx = gene_to_tx
        self._genename_to_tx = genename_to_tx
        self._cache_key = cache_key

        # Versionless alias map (match ENST… to ENST….7)
        self._tx_by_id_novers: Dict[str, TxRecord] = {}
        for tid, rec in tx_by_id.items():
            base = re.sub(r"\.\d+$", "", tid)
            self._tx_by_id_novers.setdefault(base, rec)

    # ---------------------------------------------------------------------
    @classmethod
    def build(cls, gtf_path: str, cache_dir: Optional[str] = None, *,
              keep_features: Tuple[str, ...] = ("exon", "CDS", "5UTR", "3UTR"),
              protein_coding_only: bool = False,
              keep_chroms: Optional[Tuple[str, ...]] = None) -> "TranscriptIndex":

        gtf_path = str(pathlib.Path(gtf_path).resolve())

        salt = f".pc{int(protein_coding_only)}.kf{hashlib.sha1(','.join(keep_features).encode()).hexdigest()[:6]}"
        if keep_chroms:
            salt += f".kc{hashlib.sha1(','.join(keep_chroms).encode()).hexdigest()[:6]}"

        key = cls._cache_key(gtf_path) + salt
        cache_file = (os.path.join(cache_dir, f"txindex.{key}.pkl") if cache_dir else None)

        if cache_file and os.path.exists(cache_file):
            with open(cache_file, "rb") as f:
                return pickle.load(f)

        # 1) Load & normalize schema
        df = pr.read_gtf(gtf_path).df

        # Column normalization
        desired = ["Feature","Chromosome","Start","End","Strand",
                   "gene_id","gene_name","transcript_id",
                   "transcript_name","transcript_type"]

        if "transcript_type" not in df.columns and "transcript_biotype" in df.columns:
            df["transcript_type"] = df["transcript_biotype"]

        for c in desired:
            if c not in df.columns:
                df[c] = pd.NA

        df = df[desired].copy()

        # Normalize UTR labels
        df["Feature"] = df["Feature"].replace({
            "five_prime_UTR": "5UTR",
            "three_prime_UTR": "3UTR"
        })

        # Optional filters
        if keep_chroms is not None:
            df = df[df["Chromosome"].isin(keep_chroms)]
        if protein_coding_only and "transcript_type" in df.columns:
            df = df[df["transcript_type"] == "protein_coding"]

        df = df[df["Feature"].isin(keep_features)]

        # Dtypes
        df["Start"] = pd.to_numeric(df["Start"], errors="coerce").astype("Int64").astype("float64").astype("int32", errors="ignore")
        df["End"] = pd.to_numeric(df["End"], errors="coerce").astype("Int64").astype("float64").astype("int32", errors="ignore")
        df["strand_int"] = df["Strand"].map({"+": 1, "-": -1}).astype("Int8").fillna(0).astype("int8")

        if df.empty or df["transcript_id"].isna().all():
            raise RuntimeError(f"No transcript rows retained for {gtf_path}. Check file, species, or filters.")
        # 2) Global stable sort
        df.sort_values(["transcript_id", "Start", "End"],
                       kind="mergesort", inplace=True, ignore_index=True)

        # 3) Factorize per-transcript slices
        tid_codes, tid_uniques = pd.factorize(df["transcript_id"].astype(str), sort=False)
        change = np.r_[True, tid_codes[1:] != tid_codes[:-1], True]
        bounds = np.flatnonzero(change)
        starts, ends = bounds[:-1], bounds[1:]

        # Column numpy views
        feat = df["Feature"].to_numpy()
        chrom = df["Chromosome"].astype(str).to_numpy()
        start = df["Start"].to_numpy()
        end = df["End"].to_numpy()
        strand_int = df["strand_int"].to_numpy()
        gene_id = df["gene_id"].astype(str).to_numpy()
        gene_name = df["gene_name"].astype(str).to_numpy()
        tx_name = df["transcript_name"].astype(str).to_numpy()
        tx_type = df["transcript_type"].astype(str).to_numpy()

        # Feature masks
        f_exon = (feat == "exon")
        f_cds = (feat == "CDS")
        f_u5 = (feat == "5UTR")
        f_u3 = (feat == "3UTR")

        def _blocks_slice(i0: int, i1: int, mask: np.ndarray) -> np.ndarray:
            if i1 <= i0:
                return np.empty((0, 2), np.int32)
            loc = np.nonzero(mask[i0:i1])[0]
            if loc.size == 0:
                return np.empty((0, 2), np.int32)
            s = start[i0 + loc]
            e = end[i0 + loc]
            out = np.empty((loc.size, 2), dtype=np.int32)
            out[:, 0] = s
            out[:, 1] = e
            return out

        def _first_non_empty(a: np.ndarray) -> Optional[str]:
            for v in a:
                if v and v != "nan":
                    return str(v)
            return None

        tx_by_id: Dict[str, TxRecord] = {}
        gene_to_tx: Dict[str, List[str]] = {}
        genename_to_tx: Dict[str, List[str]] = {}

        for code, i0, i1 in zip(range(len(starts)), starts, ends):
            tid = str(tid_uniques[code])
            chrom0 = chrom[i0]
            sgn = int(strand_int[i0]) if strand_int[i0] in (1, -1) else 0
            gid = _first_non_empty(gene_id[i0:i1])
            gnm = _first_non_empty(gene_name[i0:i1])
            tnm = _first_non_empty(tx_name[i0:i1])
            ttp = _first_non_empty(tx_type[i0:i1])

            # guard against NaN starts/ends
            s_min = start[i0:i1][~np.isnan(start[i0:i1])]
            e_max = end[i0:i1][~np.isnan(end[i0:i1])]
            if s_min.size == 0 or e_max.size == 0:
                continue

            rec = TxRecord(
                transcript_id=tid,
                gene_id=gid,
                gene_name=gnm,
                transcript_name=tnm,
                transcript_type=ttp,
                chrom=chrom0,
                strand=sgn,
                span=(int(np.min(s_min)), int(np.max(e_max))),
                exons=_blocks_slice(i0, i1, f_exon),
                cds=_blocks_slice(i0, i1, f_cds),
                utr5=_blocks_slice(i0, i1, f_u5),
                utr3=_blocks_slice(i0, i1, f_u3),
            )

            tx_by_id[tid] = rec
            if gid:
                gene_to_tx.setdefault(gid, []).append(tid)
            if gnm:
                genename_to_tx.setdefault(gnm, []).append(tid)

        idx = cls(tx_by_id, gene_to_tx, genename_to_tx, key)

        # refuse to cache an empty index
        if cache_dir:
            if len(tx_by_id) == 0:
                raise RuntimeError("TranscriptIndex built empty — refusing to cache. Check GTF and filters.")
            os.makedirs(cache_dir, exist_ok=True)
            with open(cache_file, "wb") as f:
                pickle.dump(idx, f, protocol=pickle.HIGHEST_PROTOCOL)

        return idx

    # --------- version-tolerant lookups ---------
    def _resolve(self, tid: str) -> TxRecord:
        if tid in self._tx_by_id:
            return self._tx_by_id[tid]
        base = re.sub(r"\.\d+$", "", tid)
        rec = self._tx_by_id_novers.get(base)
        if rec is None:
            raise KeyError(tid)
        return rec

    def tx(self, tid: str) -> TxRecord:
        return self._resolve(tid)

    def exons(self, tid: str) -> np.ndarray:
        return self._resolve(tid).exons

    def cds(self, tid: str) -> np.ndarray:
        return self._resolve(tid).cds

    def utr5(self, tid: str) -> np.ndarray:
        return self._resolve(tid).utr5

    def utr3(self, tid: str) -> np.ndarray:
        return self._resolve(tid).utr3

    def junctions(self, tid: str) -> np.ndarray:
        return self._resolve(tid).junctions

    def chrom(self, tid: str) -> str:
        return self._resolve(tid).chrom

    def strand(self, tid: str) -> int:
        return self._resolve(tid).strand

    def span(self, tid: str) -> Tuple[int, int]:
        return self._resolve(tid).span

    def transcripts_of_gene(self, key: str) -> List[str]:
        return self._gene_to_tx.get(key, self._genename_to_tx.get(key, []))


    # --------- gene name mapping ---------
    def add_gene_names(self, gene_name_map: Union[str, Dict[str, str], pd.DataFrame],
                        transcript_id_col: Optional[str] = None,
                        gene_name_col: Optional[str] = None) -> int:
        """Add or update gene_name for transcripts using a mapping.

        Useful for GFF files (like PacBio) that lack gene_name attributes.
        Updates records in-place and rebuilds the genename_to_tx index.

        Parameters
        ----------
        gene_name_map : str, dict, or DataFrame
            Mapping from transcript_id to gene_name. Can be:
            - Path to TSV file with columns [transcript_id, gene_name]
            - Dict mapping transcript_id -> gene_name
            - DataFrame (use transcript_id_col and gene_name_col to specify columns)
            For PacBio format where transcript_id contains gene name suffix
            (e.g., 'PB.10.82:DDX11L17'), the base transcript_id (before ':')
            will be extracted for matching.
        transcript_id_col : str, optional
            Column name for transcript_id in DataFrame. If None, uses first column.
        gene_name_col : str, optional
            Column name for gene_name in DataFrame. If None, uses second column.

        Returns
        -------
        int
            Number of transcripts updated.
        """
        # Parse the mapping into a dict
        if isinstance(gene_name_map, str):
            # Load from TSV file
            map_df = pd.read_csv(gene_name_map, sep="\t", header=None, names=["tid_raw", "gene_name"])
            mapping = {}
            for _, row in map_df.iterrows():
                tid_raw = str(row["tid_raw"])
                gnm = str(row["gene_name"])
                # Handle PacBio format: PB.10.82:DDX11L17 -> PB.10.82
                if ":" in tid_raw:
                    tid = tid_raw.split(":")[0]
                else:
                    tid = tid_raw
                mapping[tid] = gnm
        elif isinstance(gene_name_map, pd.DataFrame):
            mapping = {}
            # Use specified columns, or fall back to positional
            if transcript_id_col and gene_name_col:
                tid_col, gnm_col = transcript_id_col, gene_name_col
            elif "transcript_id" in gene_name_map.columns and "gene_name" in gene_name_map.columns:
                tid_col, gnm_col = "transcript_id", "gene_name"
            else:
                tid_col, gnm_col = gene_name_map.columns[0], gene_name_map.columns[1]
            for _, row in gene_name_map.iterrows():
                tid_raw = str(row[tid_col])
                gnm = str(row[gnm_col])
                if ":" in tid_raw:
                    tid = tid_raw.split(":")[0]
                else:
                    tid = tid_raw
                mapping[tid] = gnm
        else:
            # Assume it's a dict
            mapping = {}
            for tid_raw, gnm in gene_name_map.items():
                if ":" in tid_raw:
                    tid = tid_raw.split(":")[0]
                else:
                    tid = tid_raw
                mapping[tid] = gnm

        # Update records
        updated = 0
        new_tx_by_id = {}
        new_genename_to_tx: Dict[str, List[str]] = {}

        for tid, rec in self._tx_by_id.items():
            gnm = mapping.get(tid)
            # Check if we should update: gnm is valid AND rec.gene_name is missing/NA
            gnm_valid = gnm and gnm not in ("nan", "<NA>", "None", "")
            rec_missing = rec.gene_name is None or pd.isna(rec.gene_name) or str(rec.gene_name) in ("nan", "<NA>", "None", "")
            if gnm_valid and rec_missing:
                # Create new record with updated gene_name
                new_rec = TxRecord(
                    transcript_id=rec.transcript_id,
                    gene_id=rec.gene_id,
                    gene_name=gnm,
                    transcript_name=rec.transcript_name,
                    transcript_type=rec.transcript_type,
                    chrom=rec.chrom,
                    strand=rec.strand,
                    span=rec.span,
                    exons=rec.exons,
                    cds=rec.cds,
                    utr5=rec.utr5,
                    utr3=rec.utr3,
                )
                new_tx_by_id[tid] = new_rec
                updated += 1
            else:
                new_tx_by_id[tid] = rec
                gnm = rec.gene_name

            # Rebuild genename_to_tx
            if gnm and gnm != "nan":
                new_genename_to_tx.setdefault(gnm, []).append(tid)

        self._tx_by_id = new_tx_by_id
        self._genename_to_tx = new_genename_to_tx

        # Rebuild versionless lookup
        self._tx_by_id_novers = {}
        for tid, rec in self._tx_by_id.items():
            base = re.sub(r"\\.\d+$", "", tid)
            self._tx_by_id_novers.setdefault(base, rec)

        return updated

    # --------- pigeon classification ---------
    def add_pigeon_classification(self, classification_file: str, use_ref_ids: bool = True) -> int:
        """Add metadata from PacBio pigeon classification file.
        
        Adds CDS coordinates, associated_transcript, subcategory, and NMD prediction
        from the pigeon classification.txt file.
        
        Parameters
        ----------
        classification_file : str
            Path to pigeon_filtered.classification.txt file.
        use_ref_ids : bool
            If True, remap transcript IDs to use reference IDs (e.g., ENST...) 
            when available, keeping PB.* IDs only for novel transcripts.
            This helps match adata that uses mixed ID formats. Default True.
            
        Returns
        -------
        int
            Number of transcripts updated with CDS information.
        """
        import pandas as pd
        
        # Load classification file
        clf = pd.read_csv(classification_file, sep="\t", low_memory=False)
        
        # Create metadata dict if not exists
        if not hasattr(self, '_metadata'):
            self._metadata: Dict[str, Dict] = {}
        
        # Create ID mapping dict: pb_id -> new_id
        if not hasattr(self, '_id_map'):
            self._id_map: Dict[str, str] = {}
        
        updated_cds = 0
        new_tx_by_id = {}
        new_genename_to_tx: Dict[str, List[str]] = {}
        
        for _, row in clf.iterrows():
            pb_id = str(row['isoform'])
            assoc_tx = row.get('associated_transcript')
            
            # Determine the ID to use
            if use_ref_ids and pd.notna(assoc_tx) and assoc_tx != 'novel' and not str(assoc_tx).startswith('PB.'):
                new_id = str(assoc_tx)
            else:
                new_id = pb_id
            
            # Store ID mapping
            self._id_map[pb_id] = new_id
            self._id_map[new_id] = new_id  # Also map new_id to itself for lookups
            
            # Store metadata under both IDs
            meta = {
                'pb_id': pb_id,
                'associated_gene': row.get('associated_gene'),
                'associated_transcript': assoc_tx,
                'structural_category': row.get('structural_category'),
                'subcategory': row.get('subcategory'),
                'coding': row.get('coding'),
                'predicted_NMD': row.get('predicted_NMD'),
            }
            self._metadata[pb_id] = meta
            self._metadata[new_id] = meta
            
            # Update transcript record
            if pb_id in self._tx_by_id:
                rec = self._tx_by_id[pb_id]
                gene_name = row.get('associated_gene')
                
                # Compute CDS blocks from genomic coordinates
                cds_start = row.get('CDS_genomic_start')
                cds_end = row.get('CDS_genomic_end')
                
                new_cds = rec.cds
                if pd.notna(cds_start) and pd.notna(cds_end) and rec.exons.size > 0:
                    cds_start, cds_end = int(cds_start), int(cds_end)
                    if cds_start > 0 and cds_end > 0:
                        # Compute CDS blocks by intersecting with exons
                        cds_blocks = []
                        for ex_start, ex_end in rec.exons:
                            block_start = max(ex_start, cds_start)
                            block_end = min(ex_end, cds_end)
                            if block_start < block_end:
                                cds_blocks.append([block_start, block_end])
                        
                        if cds_blocks:
                            new_cds = np.array(cds_blocks, dtype=np.int32)
                            updated_cds += 1
                
                # Update gene_name if needed
                rec_missing_gene = rec.gene_name is None or pd.isna(rec.gene_name) or str(rec.gene_name) in ("nan", "<NA>", "None", "")
                new_gene_name = str(gene_name) if (gene_name and pd.notna(gene_name) and rec_missing_gene) else rec.gene_name
                
                # Create updated record with new ID
                new_rec = TxRecord(
                    transcript_id=new_id,
                    gene_id=rec.gene_id,
                    gene_name=new_gene_name,
                    transcript_name=rec.transcript_name,
                    transcript_type=rec.transcript_type,
                    chrom=rec.chrom,
                    strand=rec.strand,
                    span=rec.span,
                    exons=rec.exons,
                    cds=new_cds,
                    utr5=rec.utr5,
                    utr3=rec.utr3,
                )
                new_tx_by_id[new_id] = new_rec
                
                # Update gene mappings
                if new_gene_name and str(new_gene_name) not in ("nan", "<NA>", "None", ""):
                    new_genename_to_tx.setdefault(new_gene_name, []).append(new_id)
        
        # Replace tx_by_id with remapped version
        # Keep transcripts not in classification file
        for tid, rec in self._tx_by_id.items():
            if tid not in [row['isoform'] for _, row in clf.iterrows()]:
                new_tx_by_id[tid] = rec
        
        self._tx_by_id = new_tx_by_id
        self._genename_to_tx = new_genename_to_tx
        
        # Rebuild gene_to_tx
        self._gene_to_tx = {}
        for tid, rec in self._tx_by_id.items():
            if rec.gene_id:
                self._gene_to_tx.setdefault(rec.gene_id, []).append(tid)
        
        # Rebuild versionless lookup
        self._tx_by_id_novers = {}
        for tid, rec in self._tx_by_id.items():
            base = re.sub(r"\.\d+$", "", tid)
            self._tx_by_id_novers.setdefault(base, rec)
        
        return updated_cds
    
    def get_metadata(self, tid: str) -> Optional[Dict]:
        """Get pigeon classification metadata for a transcript."""
        if not hasattr(self, '_metadata'):
            return None
        return self._metadata.get(tid)
    
    def to_gtf(self, output_path: str, include_cds: bool = True) -> None:
        """Export the transcript index to GTF format.
        
        Writes a standard GTF file with proper 1-based coordinates and CDS frame.
        
        Parameters
        ----------
        output_path : str
            Path to write the GTF file.
        include_cds : bool
            If True, include CDS features with proper frame (default True).
        """
        with open(output_path, 'w') as f:
            for tid, rec in self._tx_by_id.items():
                chrom = rec.chrom
                strand = '+' if rec.strand >= 0 else '-'
                gene_id = rec.gene_id or tid.rsplit('.', 1)[0]
                gene_name = rec.gene_name or gene_id
                
                # Get metadata if available
                meta = self.get_metadata(tid) if hasattr(self, '_metadata') else None
                
                # Build attribute string
                attrs = f'gene_id "{gene_id}"; transcript_id "{tid}"; gene_name "{gene_name}";'
                if meta:
                    if meta.get('pb_id') and meta.get('pb_id') != tid:
                        attrs += f' pb_id "{meta["pb_id"]}";'
                    if meta.get('associated_transcript'):
                        attrs += f' associated_transcript "{meta["associated_transcript"]}";'
                    if meta.get('structural_category'):
                        attrs += f' structural_category "{meta["structural_category"]}";'
                    if meta.get('subcategory'):
                        attrs += f' subcategory "{meta["subcategory"]}";'
                    if meta.get('coding'):
                        attrs += f' transcript_biotype "{meta["coding"]}";'
                    if meta.get('predicted_NMD'):
                        attrs += f' predicted_NMD "{meta["predicted_NMD"]}";'
                
                # GTF uses 1-based coordinates
                tx_start, tx_end = rec.span
                tx_start_1 = tx_start + 1  # Convert to 1-based
                
                # Write transcript/gene line
                f.write(f"{chrom}\tTranscriptData\ttranscript\t{tx_start_1}\t{tx_end}\t.\t{strand}\t.\t{attrs}\n")
                
                # Write exon lines (sorted by position)
                exons_sorted = sorted(rec.exons.tolist(), key=lambda x: x[0])
                for i, (ex_start, ex_end) in enumerate(exons_sorted):
                    exon_num = i + 1 if strand == '+' else len(exons_sorted) - i
                    exon_attrs = attrs + f' exon_number "{exon_num}";'
                    ex_start_1 = ex_start + 1  # Convert to 1-based
                    f.write(f"{chrom}\tTranscriptData\texon\t{ex_start_1}\t{ex_end}\t.\t{strand}\t.\t{exon_attrs}\n")
                
                # Write CDS lines with proper frame
                if include_cds and rec.cds.size > 0:
                    cds_sorted = sorted(rec.cds.tolist(), key=lambda x: x[0])
                    
                    # Calculate frame for each CDS block
                    # Frame = (3 - (cumulative CDS length % 3)) % 3
                    if strand == '+':
                        cumulative_len = 0
                        for cds_start, cds_end in cds_sorted:
                            frame = (3 - (cumulative_len % 3)) % 3
                            cds_start_1 = cds_start + 1  # Convert to 1-based
                            cds_attrs = attrs
                            f.write(f"{chrom}\tTranscriptData\tCDS\t{cds_start_1}\t{cds_end}\t.\t{strand}\t{frame}\t{cds_attrs}\n")
                            cumulative_len += (cds_end - cds_start)
                    else:
                        # For minus strand, process in reverse
                        cumulative_len = 0
                        for cds_start, cds_end in reversed(cds_sorted):
                            frame = (3 - (cumulative_len % 3)) % 3
                            cds_start_1 = cds_start + 1  # Convert to 1-based
                            cds_attrs = attrs
                            f.write(f"{chrom}\tTranscriptData\tCDS\t{cds_start_1}\t{cds_end}\t.\t{strand}\t{frame}\t{cds_attrs}\n")
                            cumulative_len += (cds_end - cds_start)
                
                # Write start_codon and stop_codon if CDS present
                if include_cds and rec.cds.size > 0:
                    cds_sorted = sorted(rec.cds.tolist(), key=lambda x: x[0])
                    if strand == '+':
                        # Start codon at beginning of first CDS
                        start_pos = cds_sorted[0][0] + 1  # 1-based
                        stop_pos = cds_sorted[-1][1] - 2  # Last 3 bp, 1-based
                        f.write(f"{chrom}\tTranscriptData\tstart_codon\t{start_pos}\t{start_pos + 2}\t.\t{strand}\t0\t{attrs}\n")
                        f.write(f"{chrom}\tTranscriptData\tstop_codon\t{stop_pos}\t{stop_pos + 2}\t.\t{strand}\t0\t{attrs}\n")
                    else:
                        # Minus strand: start at end, stop at beginning
                        start_pos = cds_sorted[-1][1] - 2  # 1-based
                        stop_pos = cds_sorted[0][0] + 1  # 1-based
                        f.write(f"{chrom}\tTranscriptData\tstart_codon\t{start_pos}\t{start_pos + 2}\t.\t{strand}\t0\t{attrs}\n")
                        f.write(f"{chrom}\tTranscriptData\tstop_codon\t{stop_pos}\t{stop_pos + 2}\t.\t{strand}\t0\t{attrs}\n")

    # --------- small debuggers ---------
    def summary(self) -> Dict[str, object]:
        return {
            "n_transcripts": len(self._tx_by_id),
            "n_genes_by_id": len(self._gene_to_tx),
            "n_genes_by_name": len(self._genename_to_tx),
            "cache_key": self._cache_key,
        }

    def list_transcripts(self, n: int = 10, prefix: Optional[str] = None) -> List[str]:
        ids = list(self._tx_by_id.keys())
        if prefix:
            ids = [t for t in ids if t.startswith(prefix)]
        return ids[:n]

    # --------- preprocessing helpers ---------
    def gene_transcript_table(self, use_gene_name: bool = True) -> pd.DataFrame:
        """Return DataFrame with columns [gene, transcript_id] for preprocessing functions.
        
        Parameters
        ----------
        use_gene_name : bool
            If True, use gene_name (symbol) as gene identifier; otherwise use gene_id (ENSG).
        
        Returns
        -------
        pd.DataFrame
            DataFrame with columns ['gene', 'transcript_id'], version-stripped.
        """
        rows = []
        for tid, rec in self._tx_by_id.items():
            gene = (rec.gene_name if use_gene_name and rec.gene_name else rec.gene_id) or ""
            tid_stripped = tid.split(".")[0]
            rows.append((gene, tid_stripped))
        return pd.DataFrame(rows, columns=["gene", "transcript_id"]).drop_duplicates()

    def isoforms_per_gene(self, use_gene_name: bool = True) -> pd.Series:
        """Return Series of isoform counts per gene (fast, no groupby needed).
        
        Parameters
        ----------
        use_gene_name : bool
            If True, use gene_name mapping; otherwise use gene_id mapping.
        
        Returns
        -------
        pd.Series
            Series indexed by gene with isoform counts as values.
        """
        mapping = self._genename_to_tx if use_gene_name else self._gene_to_tx
        return pd.Series({gene: len(tids) for gene, tids in mapping.items()}, name="n_isoforms")

    def transcript_length(self, tid: str) -> int:
        """Return mature transcript length (sum of exon lengths) in bp."""
        exons = self._resolve(tid).exons
        if exons.size == 0:
            return 0
        return int(np.sum(exons[:, 1] - exons[:, 0]))

    def transcript_lengths_table(self) -> pd.DataFrame:
        """Return DataFrame with transcript_id and length for all transcripts."""
        rows = []
        for tid, rec in self._tx_by_id.items():
            length = int(np.sum(rec.exons[:, 1] - rec.exons[:, 0])) if rec.exons.size > 0 else 0
            tid_stripped = tid.split(".")[0]
            gene = rec.gene_name or rec.gene_id or ""
            rows.append((tid_stripped, tid, gene, length))
        return pd.DataFrame(rows, columns=["transcript_id", "transcript_id_full", "gene", "length"])

    @staticmethod
    def _cache_key(gtf_path: str) -> str:
        st = pathlib.Path(gtf_path).stat()
        return hashlib.sha1(f"{gtf_path}|{st.st_size}|{int(st.st_mtime)}".encode()).hexdigest()[:16]
    
    def _tx_exon_lists_for_bubbles(rec: TxRecord) -> tuple[list[int], list[int]]:
        """
        Reconstruct exonStart / exonEnd lists in the same way ParseGTF does.

        For '+' strand:
        exonStart = sort(Start), exonEnd = sort(End)

        For '-' strand:
        exonStart = -sort(-End)
        exonEnd   = -sort(-Start)

        This preserves Wang's 5'/3' conventions and bubble classification semantics.
        """
        from numpy import sort as npsort

        ex = rec.exons
        if ex.size == 0:
            return [], []

        starts = ex[:, 0].astype(int)
        ends   = ex[:, 1].astype(int)

        if rec.strand == 1:   # '+'
            exonStart = npsort(starts)
            exonEnd   = npsort(ends)
        elif rec.strand == -1:  # '-'
            exonStart = -npsort(-ends)
            exonEnd   = -npsort(-starts)
        else:
            # If you ever have strand==0, you can either raise or treat as '+'.
            raise ValueError(f"Unsupported strand {rec.strand} for {rec.transcript_id}")

        return exonStart.astype(int).tolist(), exonEnd.astype(int).tolist()




