def _build_pair_df_from_index(idx: TranscriptIndex,
                                tid1: str,
                                tid2: str) -> pd.DataFrame:
        """
        Create the 2-row inputDF equivalent to Wang's ParseGTF+SmoothEnds output.
        """
        rec1 = idx.tx(tid1)
        rec2 = idx.tx(tid2)

        if rec1.chrom != rec2.chrom:
            raise ValueError(f"Transcripts are on different chromosomes: "
                            f"{rec1.chrom} vs {rec2.chrom}")
        if rec1.strand != rec2.strand:
            raise ValueError(f"Transcripts are on different strands: "
                            f"{rec1.strand} vs {rec2.strand}")

        exonStart1, exonEnd1 = _tx_exon_lists_for_bubbles(rec1)
        exonStart2, exonEnd2 = _tx_exon_lists_for_bubbles(rec2)

        strand_char = "+" if rec1.strand == 1 else "-"

        inputDF = pd.DataFrame(
            [
                [rec1.transcript_id, rec1.chrom, strand_char, exonStart1, exonEnd1],
                [rec2.transcript_id, rec2.chrom, strand_char, exonStart2, exonEnd2],
            ],
            columns=["transcript_ID", "chrom", "strand", "exonStart", "exonEnd"],
        )

        # Apply Wang's "smoothing" of overlapping terminal exons
        inputDF = SmoothEnds(inputDF)
        return inputDF
    
    
def classify_transcript_pair_from_index(idx: TranscriptIndex,
                                        tid1: str,
                                        tid2: str) -> pd.DataFrame:
    """
    Enumerate transcript-structure differences between two isoforms using Wang's
    bubble algorithm, backed by our TranscriptIndex.

    Returns a DataFrame with columns:
        ['transcript1', 'transcript2', 'event', 'coordinates']
    """
    inputDF = _build_pair_df_from_index(idx, tid1, tid2)

    chrom = str(inputDF["chrom"].iloc[0])
    strand_char = inputDF["strand"].iloc[0]

    spliceGraph = BuildSpliceGraph(inputDF)
    attributes = get_node_attributes(spliceGraph, "attribute")
    bubbles = FindBubbles(spliceGraph)

    out_rows = []
    t1 = inputDF["transcript_ID"].iloc[0]
    t2 = inputDF["transcript_ID"].iloc[1]

    for bubble in bubbles:
        event, coord = ClassifyBubble(bubble, attributes)

        if coord != "NA":
            # coord is something like "start:end;start:end" (no chrom/strand yet)
            coord = ";".join(
                [f"{chrom}:{x}:{strand_char}" for x in coord.split(";")]
            )

        out_rows.append((t1, t2, event, coord))

    return pd.DataFrame(out_rows,
                        columns=["transcript1", "transcript2", "event", "coordinates"])



