from typing import List, Optional, Tuple
import numpy as np
import pandas as pd
import pyranges as pr

def _reverse_complement(seq: str) -> str:
    """Reverse complement a DNA sequence."""
    complement = {
        'A': 'T', 'C': 'G', 'G': 'C', 'T': 'A',
        'a': 't', 'c': 'g', 'g': 'c', 't': 'a',
        'N': 'N', 'n': 'n'
    }
    return ''.join(complement.get(base, base) for base in reversed(seq))


# Standard genetic code
CODON_TABLE = {
    'TTT': 'F', 'TTC': 'F', 'TTA': 'L', 'TTG': 'L',
    'TCT': 'S', 'TCC': 'S', 'TCA': 'S', 'TCG': 'S',
    'TAT': 'Y', 'TAC': 'Y', 'TAA': '*', 'TAG': '*',
    'TGT': 'C', 'TGC': 'C', 'TGA': '*', 'TGG': 'W',
    'CTT': 'L', 'CTC': 'L', 'CTA': 'L', 'CTG': 'L',
    'CCT': 'P', 'CCC': 'P', 'CCA': 'P', 'CCG': 'P',
    'CAT': 'H', 'CAC': 'H', 'CAA': 'Q', 'CAG': 'Q',
    'CGT': 'R', 'CGC': 'R', 'CGA': 'R', 'CGG': 'R',
    'ATT': 'I', 'ATC': 'I', 'ATA': 'I', 'ATG': 'M',
    'ACT': 'T', 'ACC': 'T', 'ACA': 'T', 'ACG': 'T',
    'AAT': 'N', 'AAC': 'N', 'AAA': 'K', 'AAG': 'K',
    'AGT': 'S', 'AGC': 'S', 'AGA': 'R', 'AGG': 'R',
    'GTT': 'V', 'GTC': 'V', 'GTA': 'V', 'GTG': 'V',
    'GCT': 'A', 'GCC': 'A', 'GCA': 'A', 'GCG': 'A',
    'GAT': 'D', 'GAC': 'D', 'GAA': 'E', 'GAG': 'E',
    'GGT': 'G', 'GGC': 'G', 'GGA': 'G', 'GGG': 'G',
}

def _translate_cds(cds_seq: str) -> str:
    """Translate CDS sequence to protein, stopping at first stop codon."""
    if not cds_seq or len(cds_seq) < 3:
        return ""

    protein = []
    for i in range(0, len(cds_seq) - 2, 3):
        codon = cds_seq[i:i+3]
        aa = CODON_TABLE.get(codon, 'X')
        if aa == '*':  # Stop codon
            break
        protein.append(aa)

    return ''.join(protein)


class TranscriptData:
    """Fast, drop-in replacement for your old TranscriptData, backed by TranscriptIndex."""

    def __init__(self, gtf_file: str, reference_fasta: Optional[str] = None, cache_dir: Optional[str] = None,
                 gene_name_map: Optional[Union[str, Dict[str, str], pd.DataFrame]] = None,
                 transcript_id_col: Optional[str] = None, gene_name_col: Optional[str] = None):
        """Initialize TranscriptData from a GTF/GFF file.
        
        Parameters
        ----------
        gtf_file : str
            Path to GTF/GFF file.
        reference_fasta : str, optional
            Path to reference genome FASTA for sequence retrieval.
        cache_dir : str, optional
            Directory to cache the built index.
        gene_name_map : str, dict, or DataFrame, optional
            Mapping from transcript_id to gene_name. Useful for GFF files
            (like PacBio) that lack gene_name attributes. Can be:
            - Path to TSV file with columns [transcript_id, gene_name]
            - Dict mapping transcript_id -> gene_name  
            - DataFrame (use transcript_id_col and gene_name_col to specify columns)
            For PacBio format (e.g., 'PB.10.82:DDX11L17'), the base
            transcript_id will be extracted for matching.
        transcript_id_col : str, optional
            Column name for transcript_id when gene_name_map is a DataFrame.
        gene_name_col : str, optional
            Column name for gene_name when gene_name_map is a DataFrame.
        """
        self.gtf_file = gtf_file
        self.reference_fasta = reference_fasta
        self._idx = TranscriptIndex.build(gtf_file, cache_dir=cache_dir)
        self._fasta_handle = None
        
        # Add gene names if mapping provided
        if gene_name_map is not None:
            self._idx.add_gene_names(gene_name_map, transcript_id_col=transcript_id_col, gene_name_col=gene_name_col)

    def _get_fasta_handle(self):
        """
        Get a pysam FastaFile handle, handling both compressed and uncompressed files.
        Uses pysam instead of pyfaidx to support 64-bit genomic coordinates.
        """
        if self._fasta_handle is not None:
            return self._fasta_handle

        if not self.reference_fasta:
            return None

        import pysam
        import gzip
        import shutil
        from pathlib import Path

        fasta_path = Path(self.reference_fasta)

        # Check if file is gzipped (pysam can handle bgzipped but not regular gzip)
        if fasta_path.suffix == '.gz':
            decompressed_path = fasta_path.with_suffix('')

            if (
                not decompressed_path.exists() or
                decompressed_path.stat().st_mtime < fasta_path.stat().st_mtime
            ):
                print(f"Decompressing {fasta_path.name} for pysam...")
                with gzip.open(fasta_path, 'rb') as f_in:
                    with open(decompressed_path, 'wb') as f_out:
                        shutil.copyfileobj(f_in, f_out)
                print(f"✓ Decompressed to {decompressed_path.name}")

            self._fasta_handle = pysam.FastaFile(str(decompressed_path))
        else:
            self._fasta_handle = pysam.FastaFile(str(fasta_path))

        return self._fasta_handle

    def _wrap(self, tid: str, arr: np.ndarray, feature: str) -> pr.PyRanges:
        if arr.size == 0:
            return pr.PyRanges(pd.DataFrame(columns=["Chromosome", "Start", "End", "Strand", "Feature"]))
        chrom = self._idx.chrom(tid)
        strand = "+" if self._idx.strand(tid) == 1 else "-"
        df = pd.DataFrame({
            "Chromosome": chrom,
            "Start": arr[:, 0],
            "End": arr[:, 1],
            "Strand": strand,
            "Feature": feature
        })
        return pr.PyRanges(df)

    def get_exons(self, tid: str) -> pr.PyRanges:
        return self._wrap(tid, self._idx.exons(tid), "exon")

    def get_cds(self, tid: str) -> pr.PyRanges:
        return self._wrap(tid, self._idx.cds(tid), "CDS")

    def get_utr(self, tid: str, utr_type: str = None) -> pr.PyRanges:
        if utr_type == "5UTR":
            return self._wrap(tid, self._idx.utr5(tid), "5UTR")
        if utr_type == "3UTR":
            return self._wrap(tid, self._idx.utr3(tid), "3UTR")

        a5, a3 = self._idx.utr5(tid), self._idx.utr3(tid)
        parts = []
        if a5.size:
            parts.append(self._wrap(tid, a5, "5UTR").df)
        if a3.size:
            parts.append(self._wrap(tid, a3, "3UTR").df)
        return pr.PyRanges(pd.concat(parts, ignore_index=True)) if parts else self._wrap(
            tid, np.empty((0, 2), np.int32), "UTR"
        )

    def get_intron_ranges(self, tid: str) -> pr.PyRanges:
        ex = self._idx.exons(tid)
        if ex.shape[0] <= 1:
            return pr.PyRanges(pd.DataFrame(columns=["Chromosome", "Start", "End", "Strand"]))

        intr = np.stack([ex[:-1, 1], ex[1:, 0]], axis=1)
        chrom = self._idx.chrom(tid)
        strand = "+" if self._idx.strand(tid) == 1 else "-"
        df = pd.DataFrame({
            "Chromosome": chrom,
            "Start": intr[:, 0],
            "End": intr[:, 1],
            "Strand": strand
        })
        return pr.PyRanges(df)

    def get_exon_coords_and_strand(self, tid: str) -> Tuple[List[List[int]], Optional[int]]:
        ex = self._idx.exons(tid)
        strand = self._idx.strand(tid)
        coords = [[int(e), int(s)] for s, e in ex]
        return coords, strand

    def get_transcript_length(self, tid: str) -> int:
        ex = self._idx.exons(tid)
        return int(np.maximum(0, ex[:, 1] - ex[:, 0]).sum()) if ex.size else 0

    def get_chromosome(self, tid: str) -> Optional[str]:
        return self._idx.chrom(tid)

    def get_strand(self, tid: str) -> Optional[int]:
        return self._idx.strand(tid)

    def get_transcripts_by_gene_id(self, gid: str) -> List[str]:
        return self._idx.transcripts_of_gene(gid)

    def get_transcripts_by_gene_name(self, gnm: str) -> List[str]:
        return self._idx.transcripts_of_gene(gnm)

    def arrays(self, tid: str) -> dict:
        return {
            "chrom": self._idx.chrom(tid),
            "strand": self._idx.strand(tid),
            "span": self._idx.span(tid),
            "exons": self._idx.exons(tid),
            "cds": self._idx.cds(tid),
            "utr5": self._idx.utr5(tid),
            "utr3": self._idx.utr3(tid),
            "junctions": self._idx.junctions(tid)
        }

    # --------- preprocessing helpers ---------
    def gene_transcript_table(self, use_gene_name: bool = True) -> pd.DataFrame:
        """Return DataFrame with columns [gene, transcript_id] for preprocessing functions.
        
        Parameters
        ----------
        use_gene_name : bool
            If True, use gene_name (symbol) as gene identifier; otherwise use gene_id (ENSG).
        
        Returns
        -------
        pd.DataFrame
            DataFrame with columns ['gene', 'transcript_id'], version-stripped.
        """
        return self._idx.gene_transcript_table(use_gene_name=use_gene_name)

    def isoforms_per_gene(self, use_gene_name: bool = True) -> pd.Series:
        """Return Series of isoform counts per gene.
        
        Parameters
        ----------
        use_gene_name : bool
            If True, use gene_name mapping; otherwise use gene_id mapping.
        
        Returns
        -------
        pd.Series
            Series indexed by gene with isoform counts as values.
        """
        return self._idx.isoforms_per_gene(use_gene_name=use_gene_name)

    def transcript_length(self, tid: str) -> int:
        """Return mature transcript length (sum of exon lengths) in bp."""
        return self._idx.transcript_length(tid)

    def transcript_lengths_table(self) -> pd.DataFrame:
        """Return DataFrame with transcript_id and length for all transcripts."""
        return self._idx.transcript_lengths_table()

    def get_exon_coords_and_strand_batch_fast(self, transcript_ids: tuple[str, ...]):
        out = {}
        idx = self._idx
        for tid in transcript_ids:
            ex = idx.exons(tid)
            st = idx.strand(tid)
            if ex.size:
                arr = np.empty_like(ex)
                arr[:, 0] = ex[:, 1]
                arr[:, 1] = ex[:, 0]
                ex_ls = arr.tolist()
            else:
                ex_ls = []
            out[tid] = (ex_ls, st)
        return out

    def get_cds_bounds_batch_fast(self, transcript_ids: tuple[str, ...]):
        out = {}
        idx = self._idx
        for tid in transcript_ids:
            cds = idx.cds(tid)
            if cds.size:
                out[tid] = (int(cds[:, 0].min()), int(cds[:, 1].max()))
            else:
                out[tid] = None
        return out

    def get_transcript_info(self, transcript_id: str) -> dict:
        tid = _versionless(transcript_id)
        rec = self._idx.tx(tid)
        cds = self._idx.cds(tid)
        return {
            "transcript_id": rec.transcript_id,
            "transcript_name": rec.transcript_name or "unknown",
            "transcript_type": rec.transcript_type or "unknown",
            "gene_id": rec.gene_id,
            "gene_name": rec.gene_name,
            "cds_start": int(cds[:, 0].min()) if cds.size else None,
            "cds_end": int(cds[:, 1].max()) if cds.size else None,
            "chromosome": rec.chrom,
            "strand": "+" if rec.strand == 1 else "-"
        }

    def get_transcript_sequence(self, transcript_id: str) -> Optional[str]:
        fa = self._get_fasta_handle()
        if fa is None:
            return None

        tid = _versionless(transcript_id)
        rec = self._idx.tx(tid)

        exons = rec.exons
        chrom = rec.chrom
        strand = rec.strand

        # Use pysam.fetch() which handles 64-bit coordinates properly
        seqs = []
        for start, end in exons:
            seq = fa.fetch(chrom, int(start), int(end))
            seqs.append(seq)

        transcript_seq = ''.join(seqs)

        if strand == -1:
            transcript_seq = _reverse_complement(transcript_seq)

        return transcript_seq.upper()

    def get_cds_sequence(self, transcript_id: str) -> Optional[str]:
        fa = self._get_fasta_handle()
        if fa is None:
            return None

        tid = _versionless(transcript_id)
        rec = self._idx.tx(tid)

        cds = rec.cds
        if cds.size == 0:
            return None

        chrom = rec.chrom
        strand = rec.strand

        # Use pysam.fetch() which handles 64-bit coordinates properly
        seqs = []
        for start, end in cds:
            seq = fa.fetch(chrom, int(start), int(end))
            seqs.append(seq)

        cds_seq = ''.join(seqs)

        if strand == -1:
            cds_seq = _reverse_complement(cds_seq)

        return cds_seq.upper()

    def get_protein_sequence(self, transcript_id: str) -> Optional[str]:
        cds_seq = self.get_cds_sequence(transcript_id)
        if not cds_seq:
            return None

        return _translate_cds(cds_seq)


    def add_gene_names(self, gene_name_map: Union[str, Dict[str, str], pd.DataFrame],
                        transcript_id_col: Optional[str] = None,
                        gene_name_col: Optional[str] = None) -> int:
        """Add or update gene_name for transcripts using a mapping.

        Useful for GFF files (like PacBio) that lack gene_name attributes.
        Delegates to TranscriptIndex.add_gene_names().

        Parameters
        ----------
        gene_name_map : str, dict, or DataFrame
            Mapping from transcript_id to gene_name. Can be:
            - Path to TSV file with columns [transcript_id, gene_name]
            - Dict mapping transcript_id -> gene_name
            - DataFrame (use transcript_id_col and gene_name_col to specify columns)
            For PacBio format (e.g., 'PB.10.82:DDX11L17'), the base
            transcript_id will be extracted for matching.
        transcript_id_col : str, optional
            Column name for transcript_id when gene_name_map is a DataFrame.
        gene_name_col : str, optional
            Column name for gene_name when gene_name_map is a DataFrame.

        Returns
        -------
        int
            Number of transcripts updated.
        
        Example
        -------
        >>> td = TranscriptData("pigeon_filtered.sorted.gff")
        >>> td.add_gene_names(adata.var, transcript_id_col="transcriptId", gene_name_col="geneId")
        14891
        """
        return self._idx.add_gene_names(gene_name_map, transcript_id_col=transcript_id_col, gene_name_col=gene_name_col)

    def add_pigeon_classification(self, classification_file: str, use_ref_ids: bool = True) -> int:
        """Add metadata from PacBio pigeon classification file.
        
        Adds CDS coordinates, associated_transcript, subcategory, and NMD prediction.
        Also updates gene_name from associated_gene column.
        
        Parameters
        ----------
        classification_file : str
            Path to pigeon_filtered.classification.txt file.
        use_ref_ids : bool
            If True, remap transcript IDs to use reference IDs (e.g., ENST...) 
            when available, keeping PB.* IDs only for novel transcripts.
            This helps match adata that uses mixed ID formats. Default True.
            
        Returns
        -------
        int
            Number of transcripts updated with CDS information.
            
        Example
        -------
        >>> td = TranscriptData("pigeon_filtered.sorted.gff")
        >>> td.add_pigeon_classification("pigeon_filtered.classification.txt")
        >>> # Now IDs match adata: ENST... for known, PB.* for novel
        >>> td.get_metadata("ENST00000456328.2")
        {'pb_id': 'PB.4.4', 'associated_gene': 'DDX11L1', ...}
        """
        return self._idx.add_pigeon_classification(classification_file, use_ref_ids=use_ref_ids)
    
    def get_metadata(self, tid: str) -> Optional[Dict]:
        """Get pigeon classification metadata for a transcript.
        
        Returns dict with keys: associated_gene, associated_transcript, 
        structural_category, subcategory, coding, predicted_NMD
        """
        return self._idx.get_metadata(tid)
    
    def to_gtf(self, output_path: str, include_cds: bool = True) -> None:
        """Export the transcript data to GTF format.
        
        Saves all transcript information including CDS and metadata annotations.
        The output GTF can be loaded directly with TranscriptData() next time.
        
        Parameters
        ----------
        output_path : str
            Path to write the GTF file.
        include_cds : bool
            If True, include CDS features (default True).
            
        Example
        -------
        >>> td = TranscriptData("pigeon_filtered.sorted.gff")
        >>> td.add_pigeon_classification("pigeon_filtered.classification.txt")
        >>> td.to_gtf("augmented_transcripts.gtf")
        >>> # Next time, just load the augmented GTF:
        >>> td = TranscriptData("augmented_transcripts.gtf")
        """
        self._idx.to_gtf(output_path, include_cds=include_cds)

    def get_gene_sequences(self, gene_name: str) -> Dict[str, str]:
        transcript_ids = self.get_transcripts_by_gene_name(gene_name)

        sequences = {}
        for tid in transcript_ids:
            seq = self.get_transcript_sequence(tid)
            if seq:
                sequences[tid] = seq

        return sequences

    def get_gene_proteins(self, gene_name: str) -> Dict[str, str]:
        transcript_ids = self.get_transcripts_by_gene_name(gene_name)

        proteins = {}
        for tid in transcript_ids:
            protein = self.get_protein_sequence(tid)
            if protein:
                proteins[tid] = protein

        return proteins

    def classify_splicing_events(self, tid1: str, tid2: str) -> pd.DataFrame:
        """
        High-level wrapper: compare two isoforms using the Wang bubble classifier.

        Example:
            td = TranscriptData(gtf_file, cache_dir=...)
            td.classify_splicing_events("ENST00000335137", "ENST000004XXXX")
        """
        return classify_transcript_pair_from_index(self._idx, tid1, tid2)

