from pathlib import Path

def register_transcripts(adata, td_or_path, reference_fasta=None):
    """
    Register transcript annotations with an AnnData object.

    This stores transcript data in adata.uns so it persists with the object
    and can be reconstructed after saving/loading from h5ad.

    Parameters
    ----------
    adata : AnnData
        Annotated data object to register transcripts with
    td_or_path : TranscriptData or str or Path
        Either a TranscriptData object or path to GTF file
    reference_fasta : str or Path, optional
        Path to reference FASTA file (only used if td_or_path is a path)

    Examples
    --------
    >>> # Register from existing TranscriptData
    >>> td = TranscriptData("annotations.gtf")
    >>> register_transcripts(adata, td)
    >>>
    >>> # Or register directly from GTF path
    >>> register_transcripts(adata, "annotations.gtf", "genome.fa")
    >>>
    >>> # Now save and reload - transcript data persists
    >>> adata.write_h5ad("my_data.h5ad")
    >>> adata2 = sc.read_h5ad("my_data.h5ad")
    >>> td2 = get_transcript_data(adata2)  # Reconstructs automatically
    """
    if isinstance(td_or_path, (str, Path)):
        adata.uns['_transcript_gtf'] = str(td_or_path)
        adata.uns['_transcript_fasta'] = str(reference_fasta) if reference_fasta else None
        td = TranscriptData(str(td_or_path), reference_fasta)
    else:
        td = td_or_path
        adata.uns['_transcript_gtf'] = td.gtf_file
        adata.uns['_transcript_fasta'] = td.reference_fasta

    adata.uns['transcript_data'] = td


def get_transcript_data(adata):
    """
    Get TranscriptData from an AnnData object.

    If the TranscriptData object is cached in adata.uns, returns it directly.
    Otherwise, reconstructs it from stored GTF/FASTA paths (useful after
    loading from h5ad).

    Parameters
    ----------
    adata : AnnData
        Annotated data object with registered transcript data

    Returns
    -------
    TranscriptData
        Transcript data object

    Raises
    ------
    ValueError
        If no transcript data is registered with this AnnData

    Examples
    --------
    >>> # After loading from h5ad
    >>> adata = sc.read_h5ad("my_data.h5ad")
    >>> td = get_transcript_data(adata)
    >>> exons = td.get_exons("ENSMUST00000070533")
    """
    # Check for cached object
    if 'transcript_data' in adata.uns and adata.uns['transcript_data'] is not None:
        return adata.uns['transcript_data']

    # Reconstruct from stored paths
    if '_transcript_gtf' in adata.uns:
        td = TranscriptData(
            adata.uns['_transcript_gtf'],
            adata.uns.get('_transcript_fasta')
        )
        adata.uns['transcript_data'] = td  # Cache for next call
        return td

    raise ValueError(
        "No transcript_data found in adata.uns. "
        "Register it first with: register_transcripts(adata, td)"
    )


