# Junctions — transcript/gene enumeration + isoform-specifics
# ===========================================================
from typing import List, Optional, Literal, Tuple, Iterable
import re
import numpy as np, pandas as pd

# ---------- core per-transcript junctions ----------
def _strand_char(s: int) -> str:
    return "+" if s == 1 else "-" if s == -1 else "."

def _junction_df_for_tx(rec: TxRecord) -> pd.DataFrame:
    """
    Build a tidy DataFrame of exon–exon junctions for a single transcript.
    Coordinates are introns as **1-based closed** [start,end] (between exons).
    Donor/acceptor are on the **transcript strand** (5' donor, 3' acceptor).
    """
    ex = rec.exons
    if ex.shape[0] <= 1:
        return pd.DataFrame(columns=[
            "chrom","strand","intron_start_1b","intron_end_1b",
            "donor_pos_1b","acceptor_pos_1b","gene_id","gene_name",
            "transcript_id","exon_i","exon_j","junction_id"
        ])

    up_end   = ex[:-1, 1].astype(np.int64)
    dn_start = ex[ 1:, 0].astype(np.int64)

    intron_start_1b = up_end + 1
    intron_end_1b   = dn_start - 1
    ok = intron_end_1b >= intron_start_1b
    if not np.any(ok):
        return pd.DataFrame(columns=[
            "chrom","strand","intron_start_1b","intron_end_1b",
            "donor_pos_1b","acceptor_pos_1b","gene_id","gene_name",
            "transcript_id","exon_i","exon_j","junction_id"
        ])

    up_end   = up_end[ok]
    dn_start = dn_start[ok]
    intron_start_1b = intron_start_1b[ok]
    intron_end_1b   = intron_end_1b[ok]

    if rec.strand == 1:
        donor_pos_1b    = up_end
        acceptor_pos_1b = dn_start
    else:
        donor_pos_1b    = dn_start
        acceptor_pos_1b = up_end

    exon_i = np.arange(1, ex.shape[0], dtype=np.int64)[ok]
    exon_j = exon_i + 1

    chrom    = np.full(intron_start_1b.shape, rec.chrom, dtype=object)
    strand_c = np.full(intron_start_1b.shape, _strand_char(rec.strand), dtype=object)
    gid      = np.full(intron_start_1b.shape, rec.gene_id if rec.gene_id else "", dtype=object)
    gnm      = np.full(intron_start_1b.shape, rec.gene_name if rec.gene_name else "", dtype=object)
    tid      = np.full(intron_start_1b.shape, rec.transcript_id, dtype=object)

    df = pd.DataFrame({
        "chrom": chrom,
        "strand": strand_c,
        "intron_start_1b": intron_start_1b.astype(np.int64),
        "intron_end_1b":   intron_end_1b.astype(np.int64),
        "donor_pos_1b":    donor_pos_1b.astype(np.int64),
        "acceptor_pos_1b": acceptor_pos_1b.astype(np.int64),
        "gene_id":         gid,
        "gene_name":       gnm,
        "transcript_id":   tid,
        "exon_i":          exon_i.astype(np.int64),
        "exon_j":          exon_j.astype(np.int64),
    })
    df["junction_id"] = (
        df["chrom"].astype(str) + ":" +
        df["intron_start_1b"].astype(str) + "-" +
        df["intron_end_1b"].astype(str) + ":" +
        df["strand"].astype(str)
    )
    # compact
    df["intron_start_1b"] = df["intron_start_1b"].astype("int32")
    df["intron_end_1b"]   = df["intron_end_1b"].astype("int32")
    df["donor_pos_1b"]    = df["donor_pos_1b"].astype("int32")
    df["acceptor_pos_1b"] = df["acceptor_pos_1b"].astype("int32")
    df["exon_i"]          = df["exon_i"].astype("int16")
    df["exon_j"]          = df["exon_j"].astype("int16")
    return df

def _collapse_identical_introns(df: pd.DataFrame) -> pd.DataFrame:
    """Deduplicate identical introns and collect supporting transcript IDs."""
    if df.empty:
        return df
    grp_cols = ["chrom","strand","intron_start_1b","intron_end_1b","gene_id","gene_name"]
    g = df.groupby(grp_cols, as_index=False, sort=False)
    out = g.agg({
        "donor_pos_1b":"first",
        "acceptor_pos_1b":"first",
        "transcript_id": lambda x: sorted(set(map(str, x))),
    }).rename(columns={"transcript_id":"supporting_transcripts"})
    out["n_transcripts"] = out["supporting_transcripts"].map(len).astype("int16")
    out["junction_id"] = (
        out["chrom"].astype(str) + ":" +
        out["intron_start_1b"].astype(str) + "-" +
        out["intron_end_1b"].astype(str) + ":" +
        out["strand"].astype(str)
    )
    return out

# ---------- public enumeration & exports ----------
def gene_junctions_df(idx: TranscriptIndex, gene_key: str, *, collapse: bool=False) -> pd.DataFrame:
    """
    Junctions for all transcripts of a gene (gene_id or gene_name).
    collapse=False → per-transcript rows
    collapse=True  → unique introns + supporting_transcripts
    """
    txs: List[str] = idx.transcripts_of_gene(gene_key)
    if not txs:
        # accept a transcript id as a 'gene_key' for convenience
        try:
            idx.tx(gene_key)
            txs = [gene_key]
        except Exception:
            return pd.DataFrame(columns=[
                "chrom","strand","intron_start_1b","intron_end_1b","donor_pos_1b","acceptor_pos_1b",
                "gene_id","gene_name","transcript_id","exon_i","exon_j","junction_id"
            ])
    parts = []
    for tid in txs:
        try:
            parts.append(_junction_df_for_tx(idx.tx(tid)))
        except KeyError:
            pass
    if not parts:
        return pd.DataFrame(columns=[
            "chrom","strand","intron_start_1b","intron_end_1b","donor_pos_1b","acceptor_pos_1b",
            "gene_id","gene_name","transcript_id","exon_i","exon_j","junction_id"
        ])
    df = pd.concat(parts, ignore_index=True)
    if collapse:
        df = _collapse_identical_introns(df)
        return df.sort_values(["chrom","intron_start_1b","intron_end_1b","strand"], kind="mergesort", ignore_index=True)
    else:
        return df.sort_values(["transcript_id","intron_start_1b"], kind="mergesort", ignore_index=True)

def _to_bed12_regtools(df: pd.DataFrame, name_field: str="junction_id", label_prefix: Optional[str]="JUNC") -> pd.DataFrame:
    """
    Minimal regtools-like BED12 for junctions using two 1bp blocks at intron edges.
    BED12 columns: chrom, start, end, name, score, strand, thickStart, thickEnd, itemRgb, blockCount, blockSizes, blockStarts
    """
    cols = ["chrom","start","end","name","score","strand","thickStart","thickEnd","itemRgb","blockCount","blockSizes","blockStarts"]
    if df.empty:
        return pd.DataFrame(columns=cols)

    start0 = (df["intron_start_1b"].astype(np.int64) - 1)
    end0   =  df["intron_end_1b"].astype(np.int64)

    name = df[name_field].astype(str) if name_field in df.columns else df["junction_id"].astype(str)
    if label_prefix:
        name = (label_prefix + ":" + name).astype(str)

    bed12 = pd.DataFrame({
        "chrom": df["chrom"].astype(str),
        "start": start0,
        "end":   end0,
        "name":  name,
        "score": 0,
        "strand": df["strand"].astype(str),
        "thickStart": start0,
        "thickEnd":   end0,
        "itemRgb": "0",
        "blockCount": 2,
        "blockSizes": "1,1",
        "blockStarts": "0," + (end0 - start0 - 1).astype(str),
    })
    for c in ("start","end","thickStart","thickEnd","blockCount","score"):
        bed12[c] = bed12[c].astype("int32")
    return bed12[cols]

def gene_junctions_bed12(
    idx: TranscriptIndex,
    gene_key: str,
    *,
    collapse: bool=True,
    name_style: Literal["junction_id","short","supporting"]="junction_id",
    label_prefix: Optional[str]="JUNC"
) -> pd.DataFrame:
    """
    Return a regtools-compatible BED12.
      collapse=True  → unique introns (default)
      name_style:
        - "junction_id": chrom:start-end:strand
        - "short": gene_name|gene_id:start-end:strand
        - "supporting": junction_id|n=k  (needs collapse=True)
    """
    df = gene_junctions_df(idx, gene_key, collapse=collapse)
    if df.empty:
        return _to_bed12_regtools(df)

    if name_style == "junction_id":
        name_col = "junction_id"
        use = df
    elif name_style == "short":
        gname = df.get("gene_name", pd.Series([""]*len(df))).fillna("")
        gid   = df.get("gene_id",   pd.Series([""]*len(df))).fillna("")
        base  = np.where(gname.values != "", gname.values, gid.values)
        name  = (pd.Series(base, dtype=str) + ":" +
                 df["intron_start_1b"].astype(str) + "-" +
                 df["intron_end_1b"].astype(str) + ":" +
                 df["strand"].astype(str))
        use = df.assign(_name=name)
        name_col = "_name"
    elif name_style == "supporting" and "n_transcripts" in df.columns:
        name = (df["junction_id"].astype(str) + "|n=" + df["n_transcripts"].astype(str))
        use = df.assign(_name=name)
        name_col = "_name"
    else:
        name_col = "junction_id"
        use = df

    return _to_bed12_regtools(use, name_field=name_col, label_prefix=label_prefix)

def write_gene_junctions_bed12(idx: TranscriptIndex, gene_key: str, out_path: str, **kwargs) -> None:
    """Write regtools-compatible BED12 to disk."""
    bed12 = gene_junctions_bed12(idx, gene_key, **kwargs)
    bed12.to_csv(out_path, sep="\t", header=False, index=False)

def gene_junctions_bed6(idx: TranscriptIndex, gene_key: str, *, collapse: bool=True, name_field: str="junction_id") -> pd.DataFrame:
    """Optional BED6 exporter."""
    df = gene_junctions_df(idx, gene_key, collapse=collapse)
    if df.empty:
        return pd.DataFrame(columns=["chrom","start","end","name","score","strand"])
    bed6 = pd.DataFrame({
        "chrom": df["chrom"].astype(str),
        "start": df["intron_start_1b"].astype(np.int64) - 1,
        "end":   df["intron_end_1b"].astype(np.int64),
        "name":  (df[name_field] if name_field in df.columns else df["junction_id"]).astype(str),
        "score": 0,
        "strand": df["strand"].astype(str),
    })
    bed6["start"] = bed6["start"].astype("int32")
    bed6["end"]   = bed6["end"].astype("int32")
    return bed6

# ---------- NEW: isoform-specific classification ----------
def classify_gene_junctions(idx: "TranscriptIndex", gene_key: str) -> pd.DataFrame:
    """
    Classify a gene's unique junctions into:
      - 'common'          : present in all transcripts
      - 'fully_unique'    : present in exactly one transcript
      - 'partially_unique': present in >1 but not all transcripts
    Returns one row per unique junction with supporting transcripts.
    """
    df = gene_junctions_df(idx, gene_key, collapse=True)
    if df.empty:
        return df.assign(classification=pd.Series(dtype=object))
    txs = idx.transcripts_of_gene(gene_key)
    n_gene_tx = max(1, len(txs))
    n_support = df["supporting_transcripts"].map(len).astype(int)
    cls = np.where(n_support == n_gene_tx, "common",
          np.where(n_support == 1, "fully_unique", "partially_unique"))
    out = df.assign(
        n_supporting=n_support.astype("int16"),
        n_gene_transcripts=np.int16(n_gene_tx),
        classification=cls.astype(str)
    )
    cat = pd.Categorical(out["classification"], ["fully_unique","partially_unique","common"], ordered=True)
    return (out.assign(_ord=cat)
               .sort_values(["_ord","chrom","intron_start_1b","intron_end_1b","strand"], kind="mergesort")
               .drop(columns=["_ord"])
               .reset_index(drop=True))

def isoform_specific_junctions(
    idx: "TranscriptIndex",
    gene_key: str,
    transcript_id: Optional[str] = None
) -> pd.DataFrame:
    """
    Return only 'fully_unique' junctions for the gene; if transcript_id is provided,
    keep only those tagging that transcript.
    """
    c = classify_gene_junctions(idx, gene_key)
    if c.empty:
        return c
    c = c[c["classification"] == "fully_unique"].copy()
    if transcript_id is not None:
        tid = re.sub(r"\.\d+$", "", str(transcript_id))
        c = c[c["supporting_transcripts"].map(lambda ts: any(re.sub(r"\.\d+$","",t)==tid for t in ts))].copy()
    # handy 0-based for joins
    c["start0"] = (c["intron_start_1b"].astype(np.int64) - 1).astype("int32")
    c["end0"]   = c["intron_end_1b"].astype("int32")
    return c

def choose_transcript_sentinels(idx: "TranscriptIndex", gene_key: str) -> pd.DataFrame:
    """
    Pick at least one fully-unique junction per transcript (sentinel).
    Heuristic: prefer the widest intron if multiple choices exist.
    """
    u = isoform_specific_junctions(idx, gene_key)
    if u.empty: return pd.DataFrame(columns=["transcript_id","chrom","start0","end0","strand","junction_id"])
    rows = []
    for _, r in u.iterrows():
        for tid in r["supporting_transcripts"]:
            rows.append({
                "transcript_id": tid,
                "chrom": r["chrom"],
                "start0": int(r["intron_start_1b"] - 1),
                "end0":   int(r["intron_end_1b"]),
                "strand": r["strand"],
                "junction_id": r["junction_id"],
                "width":  int(r["intron_end_1b"] - r["intron_start_1b"]),
            })
    df = pd.DataFrame(rows)
    if df.empty: return df
    return (df.sort_values(["transcript_id","width"], ascending=[True, False])
              .drop_duplicates(subset=["transcript_id"])
              .drop(columns=["width"])
              .reset_index(drop=True))

# ---------- regtools interop + "expressed-uniqueness" ----------
def read_regtools_bed12(path: str) -> pd.DataFrame:
    """
    Read a BED12 (or BED6) junction file (e.g., regtools `junctions extract`).
    Returns columns: chrom,start0,end0,strand,count (score used when present).
    """
    cols12 = ["chrom","start","end","name","score","strand","thickStart","thickEnd","itemRgb","blockCount","blockSizes","blockStarts"]
    df = pd.read_csv(path, sep="\t", header=None, comment="#")
    if df.shape[1] >= 12:
        df = df.iloc[:, :12]; df.columns = cols12
    elif df.shape[1] >= 6:
        df = df.iloc[:, :6];  df.columns = cols12[:6]
    else:
        raise ValueError("BED must have at least 6 columns.")
    out = pd.DataFrame({
        "chrom":  df["chrom"].astype(str),
        "start0": df["start"].astype("int64").astype("int32"),
        "end0":   df["end"].astype("int64").astype("int32"),
        "strand": df["strand"].astype(str)
    })
    if "score" in df.columns:
        with np.errstate(all="ignore"):
            cnt = pd.to_numeric(df["score"], errors="coerce")
        out["count"] = cnt.fillna(0).astype("int32")
    else:
        out["count"] = 0
    return out

def _norm_chr(s: pd.Series) -> pd.Series:
    x = s.astype(str)
    return x.str.replace(r"^chr(?=\w)", "", regex=True)

def match_counts_to_unique(
    unique_df: pd.DataFrame,
    counts_df: pd.DataFrame,
    min_count: int = 1
) -> pd.DataFrame:
    """
    Left-join observed counts onto the 'fully_unique' junctions by (chrom,start0,end0,strand).
    Filter to expressed sentinels (count >= min_count).
    """
    if unique_df.empty:
        return unique_df
    left = unique_df.copy()
    right = counts_df.copy()
    left["_chr_norm"]  = _norm_chr(left["chrom"])
    right["_chr_norm"] = _norm_chr(right["chrom"])
    m = left.merge(
        right.rename(columns={"chrom":"chrom_obs"})[["_chr_norm","start0","end0","strand","count"]],
        how="left", on=["_chr_norm","start0","end0","strand"]
    ).drop(columns=["_chr_norm"])
    m["count"] = m["count"].fillna(0).astype("int32")
    return m[m["count"] >= int(min_count)].copy()

def isoform_specific_among_expressed(
    idx: "TranscriptIndex",
    gene_key: str,
    counts_df: pd.DataFrame,
    *,
    min_count: int = 1
) -> pd.DataFrame:
    """
    Practical variant: compute 'fully unique' **among expressed transcripts** only.
    A transcript is considered expressed if ANY of its per-transcript junctions has count ≥ min_count.
    """
    # per-transcript junctions
    per_tx = gene_junctions_df(idx, gene_key, collapse=False)
    if per_tx.empty:
        return per_tx.iloc[:0].copy()

    # observed junctions set
    obs = counts_df.copy()
    if obs.empty:
        return per_tx.iloc[:0].copy()
    obs["_chr_norm"] = _norm_chr(obs["chrom"])
    obs_key = set(zip(obs["_chr_norm"], obs["start0"].astype(int), obs["end0"].astype(int), obs["strand"].astype(str)))

    # mark transcripts that have at least one observed junction
    per_tx["_chr_norm"] = _norm_chr(per_tx["chrom"])
    per_tx["start0"] = per_tx["intron_start_1b"].astype(int) - 1
    per_tx["end0"]   = per_tx["intron_end_1b"].astype(int)
    per_tx["key"] = list(zip(per_tx["_chr_norm"], per_tx["start0"], per_tx["end0"], per_tx["strand"].astype(str)))
    tx_expressed = (per_tx.groupby("transcript_id")["key"]
                         .apply(lambda ks: any(k in obs_key for k in ks))
                         .to_dict())

    expressed_txs = {t for t, ok in tx_expressed.items() if ok}
    if not expressed_txs:
        return per_tx.iloc[:0].copy()

    # collapse unique junctions and re-evaluate support only among expressed txs
    uniq = _collapse_identical_introns(per_tx.drop(columns=["_chr_norm","start0","end0","key"]))
    def _support_expressed(ts: Iterable[str]) -> list[str]:
        return sorted([t for t in ts if t in expressed_txs])
    uniq["supporting_transcripts_expressed"] = uniq["supporting_transcripts"].map(_support_expressed)
    uniq["n_supporting_expressed"] = uniq["supporting_transcripts_expressed"].map(len).astype("int16")

    # keep those unique among expressed (exactly one)
    out = uniq[uniq["n_supporting_expressed"] == 1].copy()
    out["start0"] = (out["intron_start_1b"].astype(int) - 1).astype("int32")
    out["end0"]   = out["intron_end_1b"].astype("int32")
    return out.reset_index(drop=True)
